{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js"
  }
}
import http from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync, readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = dirname(fileURLToPath(import.meta.url));
const port = Number.parseInt(process.env.PORT ?? '8080', 10);
const databasePath = process.env.DB_PATH ?? join(root, 'data', 'workboard.sqlite');
mkdirSync(dirname(databasePath), { recursive: true });
const db = new DatabaseSync(databasePath);
db.exec(`CREATE TABLE IF NOT EXISTS projects (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
)`);
db.exec(`CREATE TABLE IF NOT EXISTS tasks (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1)),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
)`);

const send = (res, status, body, contentType = 'application/json; charset=utf-8') => {
  res.writeHead(status, { 'Content-Type': contentType, 'Cache-Control': 'no-store' });
  res.end(typeof body === 'string' || Buffer.isBuffer(body) ? body : JSON.stringify(body));
};

async function readJson(req) {
  let body = '';
  for await (const chunk of req) {
    body += chunk;
    if (body.length > 1_000_000) throw new Error('Request body too large');
  }
  return JSON.parse(body || '{}');
}

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, `http://${req.headers.host ?? 'localhost'}`);
  if (req.method === 'GET' && url.pathname === '/health') {
    return send(res, 200, { status: 'ok' });
  }
  if (req.method === 'GET' && url.pathname === '/api/projects') {
    return send(res, 200, db.prepare('SELECT id, name FROM projects ORDER BY id').all());
  }
  if (req.method === 'POST' && url.pathname === '/api/projects') {
    try {
      const payload = await readJson(req);
      const name = typeof payload.name === 'string' ? payload.name.trim() : '';
      if (!name) return send(res, 400, { error: 'Project name is required' });
      const result = db.prepare('INSERT INTO projects (name) VALUES (?)').run(name);
      return send(res, 201, { id: Number(result.lastInsertRowid), name });
    } catch {
      return send(res, 400, { error: 'Invalid request' });
    }
  }
  const tasksMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks$/);
  if (tasksMatch && req.method === 'GET') {
    const projectId = Number(tasksMatch[1]);
    if (!db.prepare('SELECT 1 FROM projects WHERE id = ?').get(projectId)) return send(res, 404, { error: 'Project not found' });
    return send(res, 200, db.prepare('SELECT id, project_id AS projectId, title, completed FROM tasks WHERE project_id = ? ORDER BY id').all(projectId).map((task) => ({ ...task, completed: Boolean(task.completed) })));
  }
  if (tasksMatch && req.method === 'POST') {
    try {
      const projectId = Number(tasksMatch[1]);
      if (!db.prepare('SELECT 1 FROM projects WHERE id = ?').get(projectId)) return send(res, 404, { error: 'Project not found' });
      const payload = await readJson(req);
      const title = typeof payload.title === 'string' ? payload.title.trim() : '';
      if (!title) return send(res, 400, { error: 'Task title is required' });
      const result = db.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)').run(projectId, title);
      return send(res, 201, { id: Number(result.lastInsertRowid), projectId, title, completed: false });
    } catch {
      return send(res, 400, { error: 'Invalid request' });
    }
  }
  const taskMatch = url.pathname.match(/^\/api\/tasks\/(\d+)$/);
  if (taskMatch && req.method === 'PATCH') {
    try {
      const payload = await readJson(req);
      if (typeof payload.completed !== 'boolean') return send(res, 400, { error: 'Completion state is required' });
      const result = db.prepare('UPDATE tasks SET completed = ? WHERE id = ?').run(payload.completed ? 1 : 0, Number(taskMatch[1]));
      if (!result.changes) return send(res, 404, { error: 'Task not found' });
      return send(res, 200, { id: Number(taskMatch[1]), completed: payload.completed });
    } catch {
      return send(res, 400, { error: 'Invalid request' });
    }
  }
  if (req.method === 'GET' && url.pathname === '/app.js') {
    return send(res, 200, readFileSync(join(root, 'app.js')), 'text/javascript; charset=utf-8');
  }
  if (req.method === 'GET' && url.pathname === '/styles.css') {
    return send(res, 200, readFileSync(join(root, 'styles.css')), 'text/css; charset=utf-8');
  }
  if (req.method === 'GET' && (url.pathname === '/' || /^\/projects\/\d+\/?$/.test(url.pathname))) {
    return send(res, 200, '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Workboard</title><link rel="stylesheet" href="/styles.css"></head><body><main id="app" aria-live="polite"></main><script type="module" src="/app.js"></script></body></html>', 'text/html; charset=utf-8');
  }
  send(res, 404, { error: 'Not found' });
});

server.listen(port, '0.0.0.0');
const app = document.querySelector('#app');

function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, (char) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
  })[char]);
}

function projectIdFromPath() {
  const match = location.pathname.match(/^\/projects\/(\d+)\/?$/);
  return match ? Number(match[1]) : null;
}

async function getProjects() {
  const response = await fetch('/api/projects');
  if (!response.ok) throw new Error('Could not load projects');
  return response.json();
}

async function render() {
  const projects = await getProjects();
  const projectId = projectIdFromPath();
  if (projectId !== null) {
    const project = projects.find((item) => item.id === projectId);
    if (!project) {
      app.innerHTML = '<h1>Project not found</h1><button type="button" id="back">Projects</button>';
      document.querySelector('#back').addEventListener('click', () => navigate('/'));
      return;
    }
    const taskResponse = await fetch(`/api/projects/${projectId}/tasks`);
    if (!taskResponse.ok) throw new Error('Could not load tasks');
    const tasks = await taskResponse.json();
    app.innerHTML = `<button type="button" id="back">Projects</button><h1>${escapeHtml(project.name)}</h1>
      <form id="task-form">
        <label for="task-title">Task title</label>
        <input id="task-title" name="title" type="text" autocomplete="off">
        <button type="submit">Create task</button>
        <p id="task-error" role="alert" hidden></p>
      </form>
      <label for="task-filter">Task filter</label>
      <select id="task-filter"><option>All</option><option>Open</option><option>Completed</option></select>
      <section id="tasks" aria-label="Tasks"></section>`;
    document.querySelector('#back').addEventListener('click', () => navigate('/'));
    const list = document.querySelector('#tasks');
    const filter = document.querySelector('#task-filter');
    const drawTasks = () => {
      const shown = tasks.filter((task) => filter.value === 'All' || (filter.value === 'Completed' ? task.completed : !task.completed));
      list.innerHTML = shown.map((task) => `<div data-testid="task-row" class="task-row">
        <span>${escapeHtml(task.title)}</span>
        <input type="checkbox" data-task-id="${task.id}" aria-label="Complete ${escapeHtml(task.title)}" ${task.completed ? 'checked' : ''}>
      </div>`).join('');
      list.querySelectorAll('[data-task-id]').forEach((checkbox) => checkbox.addEventListener('change', async () => {
        const task = tasks.find((item) => item.id === Number(checkbox.dataset.taskId));
        checkbox.disabled = true;
        try {
          const response = await fetch(`/api/tasks/${task.id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ completed: checkbox.checked }) });
          if (!response.ok) throw new Error('Could not save task');
          task.completed = checkbox.checked;
          drawTasks();
        } catch (error) { checkbox.checked = task.completed; checkbox.disabled = false; showError(error); }
      }));
    };
    filter.addEventListener('change', drawTasks);
    drawTasks();
    document.querySelector('#task-form').addEventListener('submit', async (event) => {
      event.preventDefault();
      const input = document.querySelector('#task-title');
      const error = document.querySelector('#task-error');
      const title = input.value.trim();
      if (!title) { error.textContent = 'Task title is required'; error.hidden = false; return; }
      const response = await fetch(`/api/projects/${projectId}/tasks`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title }) });
      if (!response.ok) { const result = await response.json(); error.textContent = result.error ?? 'Could not create task'; error.hidden = false; return; }
      navigate(`/projects/${projectId}`);
    });
    return;
  }

  app.innerHTML = `<h1>Workboard</h1>
    <form id="create-form">
      <label for="project-name">Project name</label>
      <input id="project-name" name="name" type="text" autocomplete="off">
      <button type="submit">Create project</button>
      <p id="error" role="alert" hidden></p>
    </form>
    <section id="projects" aria-label="Projects">${projects.map((project) => `
      <div data-testid="project-row" class="project-row">
        <span>${escapeHtml(project.name)}</span>
        <button type="button" data-project-id="${project.id}">Open project</button>
      </div>`).join('')}
    </section>`;

  document.querySelector('#create-form').addEventListener('submit', async (event) => {
    event.preventDefault();
    const input = document.querySelector('#project-name');
    const error = document.querySelector('#error');
    const name = input.value.trim();
    if (!name) {
      error.textContent = 'Project name is required';
      error.hidden = false;
      return;
    }
    const response = await fetch('/api/projects', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name }),
    });
    if (!response.ok) {
      const result = await response.json();
      error.textContent = result.error ?? 'Could not create project';
      error.hidden = false;
      return;
    }
    navigate('/');
  });
  document.querySelectorAll('[data-project-id]').forEach((button) => {
    button.addEventListener('click', () => navigate(`/projects/${button.dataset.projectId}`));
  });
}

function navigate(path) {
  history.pushState({}, '', path);
  render().catch(showError);
}

function showError(error) {
  app.innerHTML = `<p role="alert">${escapeHtml(error.message)}</p>`;
}

window.addEventListener('popstate', () => render().catch(showError));
render().catch(showError);
:root {
  color: #172033;
  background: #f4f6fa;
  font: 16px/1.5 system-ui, sans-serif;
}

body { margin: 0; }
main {
  width: min(680px, calc(100% - 40px));
  margin: 64px auto;
  padding: 32px;
  background: #fff;
  border: 1px solid #e0e5ee;
  border-radius: 12px;
  box-shadow: 0 8px 30px #1720330c;
}
h1 { margin: 0 0 24px; font-size: 2rem; }
form { display: grid; gap: 8px; margin-bottom: 28px; }
input, button { font: inherit; }
input { padding: 9px 11px; border: 1px solid #aeb8c8; border-radius: 6px; }
button { width: fit-content; padding: 8px 14px; border: 0; border-radius: 6px; color: white; background: #3157c8; cursor: pointer; }
button:hover { background: #2345aa; }
.project-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 14px 0; border-top: 1px solid #e7eaf0; }
.task-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 14px 0; border-top: 1px solid #e7eaf0; }
input[type="checkbox"] { width: 20px; height: 20px; padding: 0; }
select { width: fit-content; margin: 6px 0 14px; padding: 8px 10px; font: inherit; }
#error { color: #a12222; margin: 4px 0 0; }
